import selfies, re
from rdkit import Chem
s='''[N][C][=Branch1][C][=O][O][C][C][=C][Branch2][Ring1][=Branch2][C][=Branch1][C][=O][O][C][Branch1][=Branch2][C][=C][C][=C][C][=C][Ring1][=Branch1][C][=C][C][=C][C][=C][Ring1][=Branch1][N][C][=Branch1][C][=O][C@@H1][Branch1][C][N][C@H1][Ring1][=Branch1][S][C][Ring2][Ring1][#Branch2]. [O][=C][Branch1][C][O][/C][=Branch1][=Branch2][=N][\\O][C][C][C][C][Ring1][Ring1][C][=C][S][C][Branch2][Ring1][#C][N][C][Branch1][=Branch2][C][=C][C][=C][C][=C][Ring1][=Branch1][Branch1][=Branch2][C][=C][C][=C][C][=C][Ring1][=Branch1][C][=C][C][=C][C][=C][Ring1][=Branch1][=N][Ring2][Ring1][=Branch2]. [C][N][Branch1][C][C][C][=O]. [C][N][Branch1][C][C][C][=C][C][=C][C][=C][Ring1][=Branch1]. [Cl][C][Cl]. [O][=C][Branch1][C][Cl][C][=Branch1][C][=O][Cl]'''.replace('. ',' .').replace(' .','.')
parts=s.split('.')
for i,p in enumerate(parts):
    try:
        smi=selfies.decoder(p)
        mol=Chem.MolFromSmiles(smi)
        print('PART',i+1,'SELFIES_LEN',len(p),'SMILES',smi,'VALID',mol is not None)
        if mol:
            print(' formula',Chem.rdMolDescriptors.CalcMolFormula(mol),'MW',round(Chem.Descriptors.MolWt(mol),2))
            for a in mol.GetAtoms():
                if a.GetSymbol() in ['N','O','S','Cl']:
                    print(a.GetIdx(),a.GetSymbol(),a.GetIsAromatic(),a.GetTotalDegree(),a.GetTotalNumHs())
    except Exception as e: print('PART',i+1,'ERROR',repr(e))
